{"hypotheses": [
  {
    "name": "Hypothesis_1",
    "mechanism": "The interaction between mispricing and market volatility (VIX) can be exploited by combining momentum and short-term reversal strategies, weighted against the volatility index. High volatility could lead to more mispricing, aiding the momentum strategy, while reversal benefits from overreactions in the low volatility regime.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "Mom12m"},
        {"weight": 0.5, "primitive": "STreversal"},
        {"weight": -1.0, "primitive": "betaVIX"}
      ],
      "regime": null,
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "betaVIX", "bound": "below", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 36
  },

  {
    "name": "Hypothesis_2",
    "mechanism": "Asset growth and book-to-market ratio could signal the future performance of a company, especially during market downturns. High asset growth might indicate overinvestment and future underperformance, while high book-to-market ratio could reflect undervaluation.",
    "expression": {
      "terms": [
        {"weight": -0.5, "primitive": "AssetGrowth"},
        {"weight": 1.0, "primitive": "BM"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_NEGATIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "stronger"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.4,
    "expected_decay_half_life_months": 60
  },

  {
    "name": "Hypothesis_3",
    "mechanism": "The combination of earnings consistency and short interest can provide a sign of potential stock overpricing, especially in an up market. Firms with consistent earnings but high short interest might be targeted by informed investors expecting a price correction.",
    "expression": {
      "terms": [
        {"weight": 0.5, "primitive": "EarningsConsistency"},
        {"weight": -0.5, "primitive": "ShortInterest"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.5,
    "expected_decay_half_life_months": 48
  },

  {
    "name": "Hypothesis_4",
    "mechanism": "Firms with a high ratio of cash to assets and book leverage could be undervalued, signaling a potential increase in profitability during periods when the term spread is positive.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "Cash"},
        {"weight": 1.0, "primitive": "BookLeverage"}
      ],
      "regime": "TERM_SPREAD_POSITIVE",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "TERM_SPREAD_POSITIVE", "direction": "higher"},
      {"type": "size_segment", "segment": "large", "direction": "weaker"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": null
  },

  {
    "name": "Hypothesis_5",
    "mechanism": "Combining the firm size and earnings surprise, smaller firms with positive earnings surprises could outperform in up markets as investors update their expectations.",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "Size"},
        {"weight": 1.0, "primitive": "EarningsSurprise"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.8,
    "expected_decay_half_life_months": 24
  },

  {
    "name": "Hypothesis_6",
    "mechanism": "High book-to-market ratio and R&D expenditure (relative to market cap) could signal undervaluation and innovation potential, especially in up markets.",
    "expression": {
      "terms": [
        {"weight": 1.0, "primitive": "BM"},
        {"weight": 1.0, "primitive": "RD"}
      ],
      "regime": "MKT_TRAILING_12M_UP",
      "vol_target": false
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "mega", "direction": "stronger"},
      {"type": "international", "region": "developed_ex_us", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.6,
    "expected_decay_half_life_months": 18
  },

  {
    "name": "Hypothesis_7",
    "mechanism": "High asset growth and share issuance can signal overvaluation and future underperformance, especially in down markets",
    "expression": {
      "terms": [
        {"weight": -1.0, "primitive": "AssetGrowth"},
        {"weight": -1.0, "primitive": "ShareIss1Y"}
      ],
      "regime": "MKT_TRAILING_12M_DOWN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "international", "region": "emerging", "direction": "same_sign"},
      {"type": "subperiod_consistency"}
    ],
    "expected_annualized_sharpe": 0.9,
    "expected_decay_half_life_months": 12
  },

  {
    "name": "Hypothesis_8",
    "mechanism": "Firms with low liquidity (high bid-ask spread) and high earnings surprise could experience price pressure and information asymmetry, contributing to higher future returns, particularly in high volatility regimes.",
    "expression": {
      "terms": [
        {"weight": -0.5, "primitive": "BidAskSpread"},
        {"weight": 1.0, "primitive": "EarningsSurprise"}
      ],
      "regime": "VIX_ABOVE_TRAILING_MEDIAN",
      "vol_target": true
    },
    "auxiliary_predictions": [
      {"type": "regime_interaction", "regime": "VIX_ABOVE_TRAILING_MEDIAN", "direction": "higher"},
      {"type": "size_segment", "segment": "small", "direction": "stronger"},
      {"type": "correlation", "primitive": "BidAskSpread", "bound": "above", "threshold": 0.3}
    ],
    "expected_annualized_sharpe": 0.7,
    "expected_decay_half_life_months": 30
  }
]}
